import json
from typing import Dict, Any, List
from backend.app.services.history_service import get_investigation

DISCLAIMER = """
---
### ⚠️ PHANTOM Scan Limitations & Security Notice
* This report was generated by **PHANTOM — The AI That Haunts Your Terminal**, utilizing local open-weight AI models and deterministic heuristic analysis.
* Heuristic scanning is conservative and pattern-based. This report does not replace a comprehensive manual security audit, penetration test, or compliance review.
* Sensitive credential matches in this report have been masked to prevent accidental credential leakage.
* Never share unprotected production credentials.
"""

def generate_markdown_report(data: Dict[str, Any]) -> str:
    """Generate a clean, structured, formatted Markdown investigation report."""
    project_name = data.get("project_name", "Unknown Project")
    created_at = data.get("created_at", "Unknown")
    total_files = data.get("total_files", 0)
    scanned_size_kb = round(data.get("scanned_size_bytes", 0) / 1024, 1)
    summary = data.get("summary") or "No executive summary recorded."
    findings: List[Dict[str, Any]] = data.get("findings", [])

    crit = sum(1 for f in findings if f.get("severity") == "Critical")
    high = sum(1 for f in findings if f.get("severity") == "High")
    med = sum(1 for f in findings if f.get("severity") == "Medium")
    low = sum(1 for f in findings if f.get("severity") == "Low")
    info = sum(1 for f in findings if f.get("severity") == "Informational")

    md = [
        f"# 👻 PHANTOM Investigation Report: {project_name}",
        f"**Date:** `{created_at}` | **Target Workspace:** `{data.get('workspace_path', '')}`",
        f"**Files Inspected:** {total_files} ({scanned_size_kb} KB) | **AI Entity:** `{data.get('model_used') or 'Local Heuristics'}`\n",
        "## 📊 Executive Anomaly Summary",
        f"> {summary}\n",
        "| Critical | High | Medium | Low | Informational | Total |",
        "| :---: | :---: | :---: | :---: | :---: | :---: |",
        f"| **{crit}** | **{high}** | **{med}** | **{low}** | **{info}** | **{len(findings)}** |\n",
        "---",
        "## 🔍 Discovered Anomalies & Remediation"
    ]

    if not findings:
        md.append("\n*No suspicious anomalies or exposed credentials were unearthed in this investigation.*")
    else:
        # Group by severity
        for sev in ["Critical", "High", "Medium", "Low", "Informational"]:
            sev_findings = [f for f in findings if f.get("severity") == sev]
            if not sev_findings:
                continue
            md.append(f"\n### {sev} Findings ({len(sev_findings)})")
            for idx, f in enumerate(sev_findings, start=1):
                loc = f"`{f.get('file_path')}`"
                if f.get("line_number"):
                    loc += f" (Line {f.get('line_number')})"
                md.append(f"#### {idx}. {f.get('title')}")
                md.append(f"- **Location:** {loc}")
                md.append(f"- **Category:** {f.get('category')}")
                md.append(f"- **Status:** `{f.get('status')}`")
                md.append(f"- **Explanation:** {f.get('explanation')}")
                md.append(f"- **Evidence (Redacted):** `{f.get('evidence')}`")
                md.append(f"- **Remediation:** {f.get('remediation')}\n")

    md.append(DISCLAIMER)
    return "\n".join(md)

def generate_json_report(data: Dict[str, Any]) -> Dict[str, Any]:
    """Generate a clean JSON report structure sanitized of secrets."""
    clean_data = dict(data)
    clean_data["report_disclaimer"] = (
        "Generated by PHANTOM. This scan is heuristic and educational. "
        "Sensitive values have been redacted."
    )
    return clean_data
